MakePlayRequestCmd.prototype.sendRequest = function () {
            var payload = [];
            var totalBet = this._commonui.getTotalBet();
            payload.push(new game.StakeEncoder(totalBet));
            payload.push(new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier));
            if (this._forceModel) {
                var stops = this._forceModel.forceData.positions;
                var wildMask = this._forceModel.forceData.wildMask;
                var extraXML = this._forceModel.forceData.extraXML;
                var forceDataPresent = (stops.length > 0) || (wildMask != undefined) || (extraXML != undefined);
                if (forceDataPresent) {
                    payload.push(new game.ForceEncoder(stops, wildMask, extraXML));
                    Utils.PSLog.bold("MakePlayRequestCmd - Added FORCE data to payload: ", payload);
                }
            }
            // Add HistoryReplay data if required
            if (this._historyModel.getIsHistoryReplay()) {
                Utils.PSLog.bold("MakePlayRequestCmd - HISTORY replay 'true', fetching next HISTORY state data ..");
                var historyData = this._historyModel.getNextState(true);
                if (historyData) {
                    payload.push(new game.ReplayEncoder(historyData));
                    Utils.PSLog.bold("MakePlayRequestCmd - Added HISTORY state data to payload: ", payload);
                }
                else {
                    Utils.PSLog.warn("MakePlayRequestCmd - HistoryModel did not return valid HISTORY state data");
                    return;
                }
            }
            else {
                Utils.PSLog.bold("MakePlayRequestCmd - Normal logic request, payload:", payload);
            }
            var data = new server.GLSRequest(payload);
            this._server.makeLogicRequest(data);
            this._commonui.startPlay();
        };

